(()=>{const out={};for(const property of ['-webkit-column-rule','-webkit-columns','-webkit-text-emphasis']){out[property]={};for(const value of ['none','auto','initial','1px solid red','2px','2','0','auto auto','auto 2','2 auto','10px 3','3 10px','2 3','2.0','-1','20%','red','currentcolor','circle','filled','open','filled circle','open sesame','open red triangle','"*"','"abc" red',"'x'",'"a\\22 b"','solid dotted','bogus']){const s=document.createElement('div').style;s.setProperty(property,value);out[property][value]={text:s.cssText,value:s.getPropertyValue(property),supported:CSS.supports(property,value),components:Array.from({length:s.length},(_,i)=>[s.item(i),s.getPropertyValue(s.item(i))])};}}return out})()
